// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *RefusedPosting) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *RefusedPosting) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var entry_noVal int
		if v, exists := pkMap["entry_no"]; exists {
			switch val := v.(type) {
			case int:
				entry_noVal = val
			case float64:
				entry_noVal = int(val)
			case string:
				// the key part as text: the API's "CUSTOMER1,10000"
				if n, err := strconv.Atoi(strings.TrimSpace(val)); err == nil {
					entry_noVal = n
				}
			}
		}
		return t.GetByPK(entry_noVal)
	}
	// Handle single primary key (for tables with only one PK field)
	switch pk := primaryKey.(type) {
	case int:
		return t.GetByPK(pk)
	case float64:
		return t.GetByPK(int(pk))
	case string:
		var intVal int
		if _, err := fmt.Sscanf(pk, "%d", &intVal); err == nil {
			return t.GetByPK(intVal)
		}
	}

	fmt.Printf("Error: Invalid primary key type for Refused_Posting.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *RefusedPosting) GetByPK(entry_no int) bool {
	tableName := fmt.Sprintf("%s$%s", t.company, RefusedPostingTableName)
	var entry_noVal int
	var refused_atNull sql.NullString
	var user_idNull sql.NullString
	var error_codeNull sql.NullString
	var messageNull sql.NullString
	var document_noNull sql.NullString
	var posting_dateNull sql.NullString
	var differenceNull sql.NullString
	var detailsVal []byte

	// Collect arguments for query
	args := []interface{}{
		entry_no,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT entry_no, refused_at, user_id, error_code, message, document_no, posting_date, difference, details FROM "%s" WHERE 1=1 AND entry_no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&entry_noVal,
		&refused_atNull,
		&user_idNull,
		&error_codeNull,
		&messageNull,
		&document_noNull,
		&posting_dateNull,
		&differenceNull,
		&detailsVal,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get Refused_Posting: %v\n", err)
		return false
	}

	// Populate fields
	t.Entry_no = entry_noVal
	t.Refused_at, _ = types.NewDateTimeFromString(refused_atNull.String)
	t.User_id = types.NewCode(user_idNull.String)
	t.Error_code = types.NewCode(error_codeNull.String)
	t.Message = types.NewText(messageNull.String)
	t.Document_no = types.NewCode(document_noNull.String)
	t.Posting_date = types.NewText(posting_dateNull.String)
	t.Difference = types.NewText(differenceNull.String)
	t.Details = detailsVal

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *RefusedPosting) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, RefusedPostingTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Entry_no,
		t.Refused_at,
		t.User_id,
		t.Error_code,
		t.Message,
		t.Document_no,
		t.Posting_date,
		t.Difference,
		t.Details,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (entry_no, refused_at, user_id, error_code, message, document_no, posting_date, difference, details) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (entry_no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Refused_Posting: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(RefusedPostingTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *RefusedPosting) InsertAll(records []*RefusedPosting, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Entry_no,
			r.Refused_at,
			r.User_id,
			r.Error_code,
			r.Message,
			r.Document_no,
			r.Posting_date,
			r.Difference,
			r.Details,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, RefusedPostingTableName)
	columns := []string{"entry_no", "refused_at", "user_id", "error_code", "message", "document_no", "posting_date", "difference", "details"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *RefusedPosting) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("entry_no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, RefusedPostingTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("entry_no") {
			setClauses = append(setClauses, "entry_no = ?")
			values = append(values, t.Entry_no)
		}
		if t.hasFieldChanged("refused_at") {
			setClauses = append(setClauses, "refused_at = ?")
			values = append(values, t.Refused_at)
		}
		if t.hasFieldChanged("user_id") {
			setClauses = append(setClauses, "user_id = ?")
			values = append(values, t.User_id)
		}
		if t.hasFieldChanged("error_code") {
			setClauses = append(setClauses, "error_code = ?")
			values = append(values, t.Error_code)
		}
		if t.hasFieldChanged("message") {
			setClauses = append(setClauses, "message = ?")
			values = append(values, t.Message)
		}
		if t.hasFieldChanged("document_no") {
			setClauses = append(setClauses, "document_no = ?")
			values = append(values, t.Document_no)
		}
		if t.hasFieldChanged("posting_date") {
			setClauses = append(setClauses, "posting_date = ?")
			values = append(values, t.Posting_date)
		}
		if t.hasFieldChanged("difference") {
			setClauses = append(setClauses, "difference = ?")
			values = append(values, t.Difference)
		}
		if t.hasFieldChanged("details") {
			setClauses = append(setClauses, "details = ?")
			values = append(values, t.Details)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "refused_at = ?")
		values = append(values, t.Refused_at)
		setClauses = append(setClauses, "user_id = ?")
		values = append(values, t.User_id)
		setClauses = append(setClauses, "error_code = ?")
		values = append(values, t.Error_code)
		setClauses = append(setClauses, "message = ?")
		values = append(values, t.Message)
		setClauses = append(setClauses, "document_no = ?")
		values = append(values, t.Document_no)
		setClauses = append(setClauses, "posting_date = ?")
		values = append(values, t.Posting_date)
		setClauses = append(setClauses, "difference = ?")
		values = append(values, t.Difference)
		setClauses = append(setClauses, "details = ?")
		values = append(values, t.Details)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["entry_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Entry_no)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND entry_no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Refused_Posting: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *RefusedPosting) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "entry_no":
		if old, ok := oldValue.(int); ok {
			return t.Entry_no != old
		}
		return true // Type mismatch, assume changed
	case "refused_at":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Refused_at.Equal(old)
		}
	case "user_id":
		if old, ok := oldValue.(types.Code); ok {
			return !t.User_id.Equal(old)
		}
	case "error_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Error_code.Equal(old)
		}
	case "message":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Message.Equal(old)
		}
	case "document_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Document_no.Equal(old)
		}
	case "posting_date":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Posting_date.Equal(old)
		}
	case "difference":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Difference.Equal(old)
		}
	case "details":
		// Skip comparison for BLOB fields (too large, use always modified)
		return true
	}

	return false
}

